let conversationBusy=false;
async function submit(text){
 if(!phoneStorage.writable)return toast('This tab is read-only.');if(!state.shared?.token||!navigator.onLine)return submitLocal(text);
 if(conversationBusy)return toast('Please wait for the assistant response.');
 conversationBusy=true;
 try{const pending=state.shared.pendingMessage;if(pending&&pending.text!==text)throw Error('Retry your previous message first: '+pending.text);const operationId=pending?.operationId||crypto.randomUUID();state.shared.pendingMessage={text,operationId};await persist();const result=await linking.conversation(text,operationId);state.chat.push({role:'user',text},{role:'assistant',text:result.reply});delete state.shared.pendingMessage;persist();render();$('#inference').textContent='Shared account assistant · same conversation as WhatsApp · server-side small AI';}
 catch(e){toast(e.message+' Your message was not acknowledged.');}
 finally{conversationBusy=false;}
}
async function submitLocal(text){const start=performance.now(),result=handleFarmerMessage(text,state.session,model,{lots:marketOrder(state.session)?marketPoolLots(state.lots,currentOrder()):state.lots,choices:state.choices,handovers:state.handovers,documents:state.documents,deliveryJobs:state.deliveryJobs,costs:state.costs,profile:profiles[state.profile],order:currentOrder(),offline:true}),elapsed=performance.now()-start;state.session=result.session;state.chat.push({role:'user',text},{role:'assistant',text:result.reply});if(result.lot)state.lots.push(result.lot);if(result.choice)state.choices.push(result.choice);if(result.handover)state.handovers.push(result.handover);if(result.lotUpdate)state.lots=state.lots.map(l=>l.id===result.lotUpdate.id?{...l,...result.lotUpdate}:l);if(result.supportRequest)state.supportRequests.push(result.supportRequest);if(result.document)state.documents.push(result.document);if(result.deliveryJob)state.deliveryJobs.push(result.deliveryJob);await persist();render();$('#inference').textContent=`${model.name} · ${modelBytes} bytes · ${elapsed.toFixed(2)} ms · intent ${result.intent?.intent||'confirmation'} · local JS, zero inference requests`;}
