$('#persist-storage').onclick=async()=>{try{const granted=await navigator.storage?.persist?.();state.storageEvidence={requestedAt:new Date().toISOString(),persistent:!!granted,estimate:await navigator.storage?.estimate?.()};persist();$('#storage-evidence').textContent=granted?'Persistent storage granted. Clearing site data still removes records.':'Persistent storage was not granted. Keep an exported backup.';}catch(e){toast(e.message);}};
