async function api(path,method='GET',body){const token=$('#api-key').value;if(!token)throw Error('Enter operator API key.');const response=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:body?JSON.stringify(body):undefined});const result=await response.json();if(!response.ok)throw Error(result.error||'Request failed');return result;}
$('#sync').onclick=async()=>{try{const result=await api('sync','POST',{lots:state.lots,choices:state.choices,handovers:state.handovers});state.syncReceipts.push({at:new Date().toISOString(),lots:state.lots.map(l=>l.id),choices:state.choices.map(c=>c.id),fingerprints:Object.fromEntries(state.lots.map(l=>[l.id,JSON.stringify(l)]))});persist();render();toast(`Synced ${result.lots} lots. Explicit online sync completed.`);}catch(e){toast(e.message);}};
$('#load-messages').onclick=async()=>{try{const data=await api('messages');$('#messaging-status').textContent=data.configured?'Twilio configured. Provider evidence below.':'Provider not configured. No real exchange yet.';$('#provider-messages').innerHTML=data.messages.map(m=>card(`${m.kind} · ${m.sid} · ${m.status||''} · ${m.body||m.reply||''} · ${m.at}`)).join('')||card('No provider messages recorded.');$('#provider-accounts').innerHTML=(data.accounts||[]).map(a=>card(a.name+' · '+a.location+' · ID '+a.id.slice(0,8))).join('')+(data.supportRequests||[]).map(r=>card('Apoio · '+r.farmerId.slice(0,8)+' · '+r.createdAt+' · '+r.status)).join('');for(const l of data.lots)if(!state.lots.some(x=>x.id===l.id))state.lots.push(l);persist();render();}catch(e){toast(e.message);}};
