function connectivity(){$('#connection').textContent=navigator.onLine?'● Online':'● Offline · saved on phone';}window.addEventListener('online',connectivity);window.addEventListener('offline',connectivity);connectivity();render();linking=installLinking({state,persist,render,toast,download,flush:phoneStorage.flush});installLanguageSwitch();
if('serviceWorker'in navigator){let registration;const showUpdate=()=>{if(!registration?.waiting)return;$('#update-banner').hidden=false;};navigator.serviceWorker.register('./sw.js?release=v38').then(r=>{registration=r;showUpdate();r.addEventListener('updatefound',()=>r.installing?.addEventListener('statechange',showUpdate));return navigator.serviceWorker.ready;}).then(()=>toast('Offline cache ready, including the small AI.')).catch(e=>toast('Offline installation failed. Stay connected and reload to retry: '+e.message));$('#apply-update').onclick=async()=>{try{if(Object.keys(state.session.draft||{}).length||state.session.onboarding||state.session.pendingChoice||state.session.pendingHandover||state.phoneHarvestDraft||state.session.pendingDocument||state.session.pendingDelivery||state.session.pendingAccount||state.session.pendingWithdrawal||typeof state.session.pendingNotifications==='boolean'||state.shared?.pendingMessage||state.shared?.pendingOperation)return toast('Finish or cancel the current review and any pending submission before updating.');await phoneStorage.flush();registration?.waiting?.postMessage({type:'ACTIVATE_UPDATE'});}catch(e){toast(e.message);}};navigator.serviceWorker.addEventListener('controllerchange',()=>{if(registration?.active&&$('#update-banner').hidden===false)location.reload();});}


function renderMarketplace(){
 const view=state.marketCache||state.shared?.snapshot?.marketplace||marketView(state.session,state.lots,state.choices,state.handovers);
 $('#market-status').textContent=(navigator.onLine?'Online':'Offline · cached snapshot')+' · '+(view.observedAt||'')+' · DEMONSTRATION ONLY';
 const orders=view.orders||[];
 $('#market-cards').innerHTML=orders.map(o=>'<article class="offer-row"><div><p class="eyebrow">'+esc(o.id)+' · DEMO</p><h3>'+esc(crops[o.crop]?.[state.session.account?.language==='pt'?'pt':'en']||o.crop)+'</h3><p>'+esc(o.sourceLocation)+' → '+esc(o.destination)+'</p></div><div class="offer-terms"><strong>'+esc(o.quantityKg)+' kg</strong><span>GYD '+esc(o.priceGydKg)+'/kg</span></div><p class="muted">'+esc(o.buyer)+'</p><button data-market-command="OFFER '+esc(o.id)+'">'+(state.session.account?.language==='pt'?'Revisar proposta':'Review proposal')+'</button></article>').join('')+(view.enabled?card('Pool '+view.pooledKg+'/'+view.order.quantityKg+' kg · '+view.syntheticKg+' kg fictional partner · '+view.shortfallKg+' kg missing')+card('Your allocations: '+view.ownAllocations.map(a=>a.kg+' kg · local BRL '+a.localNet.toFixed(2)+' · proposal BRL '+a.crossNet.toFixed(2)).join('; '))+card('Logistics: '+view.transport.route+' · '+view.transport.carrier+' · '+view.transport.pickup+' · BRL '+view.transport.transportBrlKg+'/kg · not booked')+card('Import / export: '+view.trade.exporter+' · '+JSON.stringify(view.trade.checks))+card(view.status+' · No dispatch authorized')+view.handovers.map(h=>card('Handover '+h.id.slice(0,8)+' · '+h.quantityKg+' kg · '+h.status)).join(''):card('Send DEMO MARKET in WhatsApp to activate the fictional example.'));
}
$('#market-cards').onclick=async e=>{const b=e.target.closest('[data-market-command]');if(!b)return;if(!state.session.account){document.querySelector('[data-tab=capture]').click();return toast('Add your first harvest or connect WhatsApp before reviewing an offer.');}document.querySelector('[data-tab=farmer]').click();if(!state.session.demoMarketplace)await submit('DEMO MARKET');if(state.session.demoMarketplace)await submit(b.dataset.marketCommand);};
$('#refresh-market').onclick=async()=>{try{if(!state.shared?.token){delete state.marketCache;renderMarketplace();return toast('Local demonstration refreshed. Link WhatsApp to load shared records.');}if(!linking?.marketplace)throw Error('Link your WhatsApp account first.');state.marketCache=await linking.marketplace();persist();renderMarketplace();}catch(e){toast(e.message);}};
setInterval(()=>{if(!$('#marketplace').hidden&&navigator.onLine&&state.shared?.token)$('#refresh-market').click();},15000);

function renderPhoneExperience(){
 const account=state.session.account,en=account?.language!=='pt',pending=Object.keys(state.session.draft||{}).length||state.session.onboarding||state.session.pendingChoice||state.session.pendingHandover||state.session.pendingDocument||state.session.pendingDelivery||state.session.pendingAccount||state.session.pendingWithdrawal||typeof state.session.pendingNotifications==='boolean';
 $('#phone-resume').textContent=pending?(en?'Your conversation is saved. Continue where you left off.':'Sua conversa foi salva. Continue de onde parou.'):(account?(en?'Welcome back, ':'Bem-vindo, ')+account.name:(en?'Start a short conversation to create your account.':'Comece uma conversa curta para criar sua conta.'));
 $('#phone-connection').textContent=!navigator.onLine?(en?'Working offline — saved on this phone. Market information may be out of date.':'Trabalhando offline — salvo neste telefone. O mercado pode estar desatualizado.'):(state.shared?.token?(en?'WhatsApp account linked. Saved changes need explicit submission.':'WhatsApp vinculado. Alterações salvas precisam de envio explícito.'):(en?'Local companion. Connect WhatsApp to share your account.':'Aplicativo local. Vincule WhatsApp para compartilhar sua conta.'));
 const statuses=$('#record-sync-status');if(statuses)statuses.textContent=recordSyncStates(state).map(x=>x.id.slice(0,8)+' · '+x.status).join('\n')||'No confirmed harvests yet.';
 const documents=$('#workflow-documents');if(documents)documents.innerHTML=state.documents.filter(d=>d.farmerId===account?.id).map(d=>'<div class=card><strong>'+esc(d.title)+'</strong><p>'+esc(d.id.slice(0,8))+' · '+esc(d.status)+'</p><button data-document-download="'+esc(d.id)+'">Download draft</button></div>').join('')||'No document drafts yet. Ask: prepare a harvest summary.';const deliveries=$('#workflow-deliveries');if(deliveries)deliveries.textContent=state.deliveryJobs.filter(j=>j.farmerId===account?.id).map(j=>j.documentId.slice(0,8)+' · '+j.channel+' · '+j.status).join('\n');
 const updates=$('#customer-updates');if(updates)updates.textContent=account?.notifications?.inApp?(pending?(en?'Action needed: review your saved conversation.':'Ação necessária: revise sua conversa salva.'):(en?'No new buyer acceptance or booked collection has been recorded.':'Nenhuma aceitação do comprador ou coleta reservada registrada.')):(en?'In-app updates are off.':'Avisos no aplicativo desativados.');
 document.querySelectorAll('.assistant-review-actions [data-command="CONFIRM"]').forEach(b=>b.disabled=!pending||!!missing(state.session.draft||{}).length&&!state.session.pendingChoice&&!state.session.pendingHandover&&!state.session.pendingDocument&&!state.session.pendingDelivery&&!state.session.pendingAccount&&!state.session.pendingWithdrawal&&typeof state.session.pendingNotifications!=='boolean'&&state.session.onboarding?.step!=='review');
}
document.querySelectorAll('[data-phone-tab]').forEach(b=>b.onclick=()=>{document.querySelector('[data-tab='+b.dataset.phoneTab+']').click();if(b.dataset.phoneTab==='farmer')$('#message')?.focus();});
window.addEventListener('online',()=>{renderPhoneExperience();if(state.shared?.token&&linking?.dirty())toast('Back online. Your saved changes are ready for review and explicit submission in Link my account.');});window.addEventListener('offline',renderPhoneExperience);renderPhoneExperience();

$('#workflow-documents').onclick=e=>{const b=e.target.closest('[data-document-download]');if(!b)return;const d=state.documents.find(x=>x.id===b.dataset.documentDownload&&x.farmerId===state.session.account?.id);if(d)download('harvestlink-'+d.id.slice(0,8)+'.txt',documentText(d));};

// The phone companion is a task interface; WhatsApp is the conversation channel.
function renderSimpleForms(){
 const account=state.session.account,fields=$('#profile-fields');if(!fields)return;
 fields.hidden=!!account;fields.disabled=!!account;
 const pending=state.session.onboarding||Object.keys(state.session.draft||{}).length||state.session.pendingChoice||state.session.pendingHandover||state.session.pendingDocument||state.session.pendingDelivery||state.session.pendingAccount||state.session.pendingWithdrawal;
 $('#action-review').hidden=!pending;$('#action-confirm').disabled=!!state.session.onboarding&&state.session.onboarding.step!=='review'||Object.keys(state.session.draft||{}).length>0&&missing(state.session.draft).length>0;
 $('#action-review-details').textContent=pending?(state.chat.at(-1)?.text||'Review before confirming.') : '';
}
let formDraft;
$('#harvest-date').value=new Date().toISOString().slice(0,10);
$('#harvest-form').onsubmit=async e=>{e.preventDefault();try{
 if(Object.keys(state.session.draft||{}).length||state.session.onboarding||state.session.pendingChoice||state.session.pendingHandover||state.session.pendingDocument||state.session.pendingDelivery)throw Error('Finish or cancel your existing review first.');
 const account=state.session.account,name=account?.name||$('#harvest-name').value.trim(),location=account?.location||$('#harvest-place').value.trim();
 formDraft=validateLot({farmer:name,location,crop:$('#harvest-crop').value,quantityKg:Number($('#harvest-weight').value),grade:$('#harvest-grade').value,harvestDate:$('#harvest-date').value,localPriceBrl:Number($('#harvest-price').value)});
 $('#harvest-review-details').innerHTML='<div class="review-facts">'+Object.entries({Farmer:name,Community:location,Crop:crops[formDraft.crop].en,Weight:formDraft.quantityKg+' kg',Quality:formDraft.grade,Date:formDraft.harvestDate,'Price nearby':'BRL '+formDraft.localPriceBrl+'/kg'}).map(([k,v])=>'<div><span>'+esc(k)+'</span><strong>'+esc(v)+'</strong></div>').join('')+'</div>';
 state.phoneHarvestDraft=Object.fromEntries(harvestInputs.map(id=>[id,$('#'+id).value]));await persist();$('#harvest-review').hidden=false;$('#harvest-form').hidden=true;
 }catch(e){toast(e.message);}};
$('#harvest-edit').onclick=()=>{$('#harvest-form').hidden=false;$('#harvest-review').hidden=true;formDraft=null;};
$('#harvest-save').onclick=async()=>{if(!formDraft||!phoneStorage.writable)return;const button=$('#harvest-save');button.disabled=true;const before=structuredClone(state);try{
 validateLot(formDraft);const now=new Date().toISOString();
 if(!state.session.account){if(!$('#harvest-consent').checked)throw Error('Confirm profile storage first.');state.session.account={id:crypto.randomUUID(),name:formDraft.farmer,location:formDraft.location,language:$('#language')?.value||'en',createdAt:now,consent:{purpose:'harvest coordination and buyer availability summaries',version:'v1',acceptedAt:now},origin:'offline-app'};}
 const lot={...formDraft,id:crypto.randomUUID(),farmerId:state.session.account.id,confirmedAt:now,confirmation:'explicit farmer confirmation',source:'offline-app',status:'available'};
 state.lots.push(lot);state.session.lastLotId=lot.id;delete state.phoneHarvestDraft;await persist();formDraft=null;$('#harvest-form').reset();$('#harvest-date').value=new Date().toISOString().slice(0,10);$('#harvest-form').hidden=false;$('#harvest-review').hidden=true;render();document.querySelector('[data-tab=account]').click();toast('Harvest saved on this phone. Share it from Account when connected.');
 }catch(e){for(const key of Object.keys(state))delete state[key];Object.assign(state,before);render();toast(e.message);}finally{button.disabled=false;}};
$('#action-confirm').onclick=()=>submit('CONFIRM');$('#action-cancel').onclick=()=>submit('CANCEL');

const harvestInputs=['harvest-name','harvest-place','harvest-crop','harvest-weight','harvest-grade','harvest-date','harvest-price'];
for(const id of harvestInputs)if(state.phoneHarvestDraft?.[id]!==undefined)$('#'+id).value=state.phoneHarvestDraft[id];
$('#harvest-form').addEventListener('input',()=>{state.phoneHarvestDraft=Object.fromEntries(harvestInputs.map(id=>[id,$('#'+id).value]));persist();});

$('#harvest-discard').onclick=async()=>{delete state.phoneHarvestDraft;formDraft=null;$('#harvest-form').reset();$('#harvest-date').value=new Date().toISOString().slice(0,10);await persist();$('#harvest-review').hidden=true;$('#harvest-form').hidden=false;document.querySelector('[data-tab=overview]').click();};

async function checkServiceHealth(){const status=$('#service-health');if(!navigator.onLine){status.textContent='Offline. Your saved records remain available; WhatsApp and sharing need a connection.';return;}if(!location.hostname.endsWith('.vercel.app')&&!['localhost','127.0.0.1'].includes(location.hostname)){status.textContent='Use your configured coordinator service to link WhatsApp. Records can be saved offline here.';return;}try{const response=await fetch('./healthz',{cache:'no-store',signal:AbortSignal.timeout(5000)});status.textContent=response.ok?'Shared service reachable. Link your number before sharing records.':'The shared service is not ready. You can still save harvests on this phone; account linking is awaiting backend configuration.';}catch{status.textContent='Shared service unreachable. Your records remain on this phone. Try linking again when the service is available.';}}
checkServiceHealth();window.addEventListener('online',checkServiceHealth);window.addEventListener('offline',checkServiceHealth);

installOfflineConversation({getState:()=>state,persist}).catch(()=>{});
